import { eventFacts, activityRange } from './facts.js';
import { uint } from './state.js';
import { isRun56Schema, hasHottestShooterPrize } from './schema.js';
import { flipFromChain } from '../app/token-units.js';

const keyOf = slot => '0x' + slot.toString(16).padStart(64, '0');
const PAYOUTS = ['CrapsHottestShooterPaid', 'CrapsBattlePaid', 'CrapsHighRollerPaid', 'CrapsProgressivePaid'];

// Craps._rankOf retains a bust's high point in its 33-bit primary slice even though
// CrapsBattle._decodeBest deliberately reports zero for progressive eligibility.
export function crapsStoredWinnerPeak(word, highLane = false) {
  const count = word & 0xffffffffn;
  const winner = (word >> (highLane ? 137n : 169n)) & 0xffffffffn;
  const complete = highLane ? Boolean(word & (1n << 169n))
    : count === ((word >> 32n) & 0xffffffffn);
  if (!count || !winner || !complete) return null;
  const score = (word >> (highLane ? 32n : 64n)) & ((1n << 105n) - 1n);
  const winningStop = score & (1n << 104n) ? 1 : 0;
  const peak = (score >> 60n) & ((1n << (winningStop ? 44n : 33n)) - 1n);
  return { peakBankrollWei: peak * 10n ** 18n, winningStop };
}

// The payout receipt is not the settlement history: a keeper can walk a field
// across many transactions, and a sole rider's payout precedes its run event.
// Attribute the complete dense seat walk, just as the replay reader does. A
// whole-day bet ID is reused in every window, so matching the ID alone is wrong.
async function winnerRuns(s, starts, events, wantedKeys) {
  const runs = new Map();
  if (!wantedKeys.size) return runs;
  const { attributeCrapsSettlements, CrapsAttributionError } = await import('./craps-engine.js');
  const days = new Set(starts.filter(row => wantedKeys.has(row.key)).map(row => Number(row.slot / 8n)));
  for (const day of days) {
    const daySlot = BigInt(day) * 8n;
    const dayN = Number((await s.field('CRAPS', '_dayTickets', daySlot)) & 0xffffffffn);
    const windows = await Promise.all(starts.filter(row => row.slot / 8n === BigInt(day)).map(async row => {
      const entrants = Number((await s.field('CRAPS', '_battles', row.key)) & 0xffffffffn);
      const fieldDayN = row.jackpot && row.slot % 8n === 7n ? 0 : dayN;
      const drawn = row.jackpot ? Number(row.args.drawnEntries) : 0;
      return { battleKey: row.key, slot: row.slot, ownN: entrants - fieldDayN - drawn,
        dayN: fieldDayN, drawn, armedBlock: BigInt(row.blockNumber) };
    }));
    const slots = new Set(windows.map(row => String(row.slot)));
    const byTx = new Map();
    for (const row of events) {
      if (!byTx.has(row.transactionHash)) byTx.set(row.transactionHash, []);
      byTx.get(row.transactionHash).push(row);
    }
    const settlements = [];
    for (const rows of byTx.values()) {
      let hint = null;
      for (const row of [...rows].reverse()) {
        if (['CrapsBattleFinalized', 'CrapsHighRollerPaid'].includes(row.name)) hint = row.args.battleKey;
        if (row.name !== 'CrapsBetSettled') continue;
        const betId = BigInt(row.args.betId), storedSlot = betId >> 64n;
        if (storedSlot !== daySlot && !slots.has(String(storedSlot))) continue;
        settlements.push({ ...row, betId, storedSlot, storedBattleKey: hint, blockNumber: BigInt(row.blockNumber) });
      }
    }
    for (const window of windows.filter(row => wantedKeys.has(row.battleKey))) {
      try {
        const assigned = attributeCrapsSettlements(windows, settlements, { requireCompleteFor: window.battleKey });
        runs.set(window.battleKey, new Map(assigned.byBattle.get(window.battleKey).map(row => [
          row.args.betId + ':' + row.args.player, BigInt(row.args.paid),
        ])));
      } catch (error) {
        // An incomplete or ambiguous field must never be published as an exact
        // total. Other completed fields can still supply their own exact rows.
        if (!(error instanceof CrapsAttributionError)) throw error;
      }
    }
  }
  return runs;
}

export async function readCrapsResults(s, url, { signal } = {}) {
  const match = url.pathname.match(/^\/game\/craps\/lobby\/(\d+)\/results$/);
  if (!match) return undefined;
  const day = uint(match[1]);
  const { fromBlock } = await activityRange(s, Math.max(1, day - 1), signal);
  const supportsHottest = await hasHottestShooterPrize();
  const legacy = isRun56Schema(), lastPeriod = legacy ? 6 : 5;
  const payoutsForSchema = PAYOUTS.filter(name => name !== 'CrapsHottestShooterPaid' || supportsHottest);
  const events = await eventFacts(s, ['CrapsBonusArmed', 'CrapsBonusOpened', 'CrapsBetSettled', 'CrapsBattleFinalized', ...payoutsForSchema,
    ...(legacy ? [] : ['JackpotBattleStarted'])], { contract: 'CRAPS', fromBlock, signal });
  const starts = events.filter(row => ['CrapsBonusArmed', 'JackpotBattleStarted'].includes(row.name)).map(row => {
    const slot = BigInt(row.args.slot), jackpot = row.name === 'JackpotBattleStarted';
    return { ...row, slot, jackpot, key: jackpot ? keyOf(slot) : row.args.battleKey };
  }).filter(row => row.slot / 8n === BigInt(day) || row.slot / 8n === BigInt(day - 1));
  const visible = new Map(starts.filter(row => row.slot / 8n === BigInt(day)
    || Number(row.slot % 8n) - 1 >= lastPeriod).map(row => [row.key, row]));
  const payouts = events.filter(row => PAYOUTS.includes(row.name) && visible.has(row.args.battleKey));
  const winners = payouts.filter(row => ['CrapsBattlePaid', 'CrapsHighRollerPaid'].includes(row.name));
  const runs = await winnerRuns(s, starts, events, new Set(winners.map(row => row.args.battleKey)));
  const peaks = new Map(await Promise.all([...new Set(winners.map(row => row.args.battleKey))].map(async key => {
    const start = visible.get(key);
    const opened = events.find(row => row.name === 'CrapsBonusOpened' && row.args.battleKey === key);
    // The jackpot round's stored bankroll is the chain's raw FLIP (whole since audit b05ea7c50);
    // decoded event amounts are already token wei.
    const bankroll = start.jackpot ? flipFromChain((await s.field('CRAPS', '_jackpotRounds', start.slot)).bankroll)
      : opened ? BigInt(opened.args.bankroll) : null;
    if (!bankroll) return [key, null];
    const main = crapsStoredWinnerPeak(await s.field('CRAPS', '_battles', key));
    const high = winners.some(row => row.name === 'CrapsHighRollerPaid' && row.args.battleKey === key)
      ? crapsStoredWinnerPeak(await s.field('CRAPS', '_highField', key), true) : null;
    return [key, { bankroll, main, high }];
  })));
  const results = winners.map(row => {
    const a = row.args, start = visible.get(a.battleKey);
    const siblings = payouts.filter(other => other.args.battleKey === a.battleKey
      && other.args.betId === a.betId && other.args.player === a.player);
    const sum = name => siblings.filter(other => other.name === name
      && !(name === 'CrapsHighRollerPaid' && other.args.bankrollRider))
      .reduce((total, other) => total + BigInt(other.args.paid ?? other.args.amount), 0n);
    const battle = sum('CrapsBattlePaid'), high = sum('CrapsHighRollerPaid'), progressive = sum('CrapsProgressivePaid');
    const run = runs.get(a.battleKey)?.get(a.betId + ':' + a.player) ?? null;
    const peak = peaks.get(a.battleKey);
    const lanePeak = peak?.[row.name === 'CrapsBattlePaid' ? 'main' : 'high'];
    return {
      day: Number(start.slot / 8n), period: Math.min(lastPeriod, Number(start.slot % 8n) - 1),
      battleKey: a.battleKey, lane: row.name === 'CrapsBattlePaid' ? 'main' : 'high', betId: a.betId, winner: a.player,
      bankrollRider: row.name === 'CrapsHighRollerPaid' ? a.bankrollRider : null,
      runPaidWei: run == null ? null : String(run), battlePaidWei: String(battle), highPaidWei: String(high),
      progressivePaidWei: String(progressive), totalWonWei: run == null ? null : String(run + battle + high + progressive + sum('CrapsHottestShooterPaid')),
      biggestDiceRunHit: null, biggestDiceRunBefore: null,
      ...(lanePeak ? { peakBankrollWei: String(lanePeak.peakBankrollWei),
        startingBankrollWei: String(peak.bankroll), winningStop: lanePeak.winningStop } : {}),
    };
  });
  return { day, results };
}
